"""Bitmap font renderer - KernosTerminal 16x32 PSF2 font embedded.
No file I/O at runtime, no pygame.font dependency."""
import base64
import struct
import pygame

_FONT_B64 = """"""

_FONT_DATA = base64.b64decode(_FONT_B64)

def _parse_psf2(data):
    magic = data[:4]
    assert magic == b"\x72\xb5\x4a\x86", "Not a PSF2 font"
    headersize = struct.unpack("<I", data[8:12])[0]
    numglyph = struct.unpack("<I", data[16:20])[0]
    bytesperglyph = struct.unpack("<I", data[20:24])[0]
    height = struct.unpack("<I", data[24:28])[0]
    width = struct.unpack("<I", data[28:32])[0]
    glyph_data = data[headersize:]
    glyphs = []
    for i in range(numglyph):
        offset = i * bytesperglyph
        glyphs.append(glyph_data[offset:offset + bytesperglyph])
    return width, height, bytesperglyph, glyphs

_WIDTH, _HEIGHT, _BYTES_PER_GLYPH, _GLYPHS = _parse_psf2(_FONT_DATA)
_BYTES_PER_ROW = (_WIDTH + 7) // 8

def text_surface(text, colour=(200, 200, 200), spacing=4):
    """Render text to a pygame Surface using the embedded PSF2 font.

    Uses a flat bytearray buffer for bulk pixel writes instead of the
    extremely slow Surface.set_at() per-pixel call.  This moves the
    glyph rasterisation into a tight Python loop writing directly into a
    contiguous bytearray, then uploads the whole buffer at once via
    pygame.image.frombuffer — a dramatic speed-up that keeps the CPU
    free for the 3D render loop.
    """
    if not text:
        return pygame.Surface((0, 0), pygame.SRCALPHA)
    lines = text.split("\n")
    max_len = max(len(l) for l in lines) if lines else 0
    total_w = max_len * (_WIDTH + spacing) + spacing
    total_h = len(lines) * (_HEIGHT + 4)

    r, g, b = colour
    buf = bytearray(total_w * total_h * 4)

    for li, line in enumerate(lines):
        y = li * (_HEIGHT + 4)
        x = spacing
        for ch in line:
            code = ord(ch)
            if code < len(_GLYPHS):
                glyph = _GLYPHS[code]
                for row in range(_HEIGHT):
                    row_start = row * _BYTES_PER_ROW
                    py = y + row
                    if py >= total_h:
                        continue
                    py_row = py * total_w * 4
                    for col in range(_WIDTH):
                        byte_idx = row_start + col // 8
                        if byte_idx < len(glyph) and (glyph[byte_idx] & (0x80 >> (col % 8))):
                            px = x + col
                            if px < total_w:
                                idx = py_row + px * 4
                                buf[idx] = r
                                buf[idx + 1] = g
                                buf[idx + 2] = b
                                buf[idx + 3] = 255
            x += _WIDTH + spacing

    return pygame.image.frombuffer(bytes(buf), (total_w, total_h), "RGBA")
